mapper.insert:
INSERT INTO SYS_ADM_INFO_TBL (
   ADM_TP	
 , ADM_NM
 , ADM_LOGN_ID
 , ADM_LOGN_PWD
 , ADM_EMAL_ADDR
 , ADM_MBL_NO
 , ADM_DEPT_NM
 , ADM_PSTN_NM
 , RGST_DT
 , RGST_SEQ
)
VALUES (
	#{admTp, jdbcType=VARCHAR}
  , 	#{admNm, jdbcType=VARCHAR}
  , 	#{admLognId, jdbcType=VARCHAR}
  , 	#{admLognPwd, jdbcType=VARCHAR}
  , 	#{admEmalAddr, jdbcType=VARCHAR}
  , 	#{admMblNo, jdbcType=VARCHAR}
  , 	#{admDeptNm, jdbcType=VARCHAR}
  , 	#{admPstnNm, jdbcType=VARCHAR}
  , CURRENT_TIMESTAMP(3)
  , #{rgstSeq, jdbcType=NUMERIC}			
)

UPDATE SYS_ADM_INFO_TBL
SET 		ADM_TP = (
					CASE
						WHEN (#{admTp, jdbcType=VARCHAR} IS NULL OR #{admTp, jdbcType=VARCHAR} = '') THEN ADM_TP
						ELSE #{admTp, jdbcType=VARCHAR}
					END
			)
		  , 	ADM_NM = (
					CASE
						WHEN (#{admNm, jdbcType=VARCHAR} IS NULL OR #{admNm, jdbcType=VARCHAR} = '') THEN ADM_NM
						ELSE #{admNm, jdbcType=VARCHAR}
					END
		   )
		  , AUTH_CID = (
					CASE
						WHEN (#{authCid, jdbcType=VARCHAR} IS NULL OR #{authCid, jdbcType=VARCHAR} = '') THEN AUTH_CID
						ELSE #{authCid, jdbcType=VARCHAR}
					END
		  	)
		  , ADM_LOGN_ID = (
					CASE
						WHEN (#{admLognId, jdbcType=VARCHAR} IS NULL OR #{admLognId, jdbcType=VARCHAR} = '') THEN ADM_LOGN_ID
						ELSE #{admLognId, jdbcType=VARCHAR}
					END
		    )
		  , ADM_LOGN_PWD = (
					CASE
						WHEN (#{admLognPwd, jdbcType=VARCHAR} IS NULL OR #{admLognPwd, jdbcType=VARCHAR} = '') THEN ADM_LOGN_PWD
						ELSE #{admLognPwd, jdbcType=VARCHAR}
					END
		    )
		  , ADM_EMAL_ADDR = (
					CASE
						WHEN (#{admEmalAddr, jdbcType=VARCHAR} IS NULL OR #{admEmalAddr, jdbcType=VARCHAR} = '') THEN ADM_EMAL_ADDR
						ELSE #{admEmalAddr, jdbcType=VARCHAR}
					END
		    )
		  , ADM_MBL_NO = (
					CASE
						WHEN (#{admMblNo, jdbcType=VARCHAR} IS NULL OR #{admMblNo, jdbcType=VARCHAR} = '') THEN ADM_MBL_NO
						ELSE #{admMblNo, jdbcType=VARCHAR}
					END
		    )
		  , ADM_DEPT_NM = (
					CASE
						WHEN (#{admDeptNm, jdbcType=VARCHAR} IS NULL OR #{admDeptNm, jdbcType=VARCHAR} = '') THEN ADM_DEPT_NM
						ELSE #{admDeptNm, jdbcType=VARCHAR}
					END
		   )
		  , ADM_PSTN_NM = (
					CASE
						WHEN (#{admPstnNm, jdbcType=VARCHAR} IS NULL OR #{admPstnNm, jdbcType=VARCHAR} = '') THEN ADM_PSTN_NM
						ELSE #{admPstnNm, jdbcType=VARCHAR}
					END
		   )
		  , INIT_PWD_CHNG_YN = (
					CASE
						WHEN (#{initPwdChngYn, jdbcType=VARCHAR} IS NULL OR #{initPwdChngYn, jdbcType=VARCHAR} = '') THEN INIT_PWD_CHNG_YN
						ELSE #{initPwdChngYn, jdbcType=VARCHAR}
					END
		   )
		  , INIT_PWD_CHNG_DT = (
					CASE
						WHEN (#{initPwdChngDt, jdbcType=VARCHAR} IS NULL OR #{initPwdChngDt, jdbcType=VARCHAR} = '') THEN INIT_PWD_CHNG_DT
						ELSE TO_TIMESTAMP(#{initPwdChngDt, jdbcType=VARCHAR}, 'YYYY-MM-DD HH:MI:SS.MS')::TIMESTAMP(3)
					END
		   )
		  , LST_LOGN_DT = (
					CASE
						WHEN (#{lstLognDt, jdbcType=VARCHAR} IS NULL OR #{lstLognDt, jdbcType=VARCHAR} = '') THEN LST_LOGN_DT
						ELSE TO_TIMESTAMP(#{lstLognDt, jdbcType=VARCHAR}, 'YYYY-MM-DD HH:MI:SS.MS')::TIMESTAMP(3)
					END
		   )	
		  , UPDT_DT  = CURRENT_TIMESTAMP(3)
		  , UPDT_SEQ = (
					CASE
						WHEN (#{updtSeq, jdbcType=NUMERIC} IS NULL OR #{updtSeq, jdbcType=NUMERIC} = 0) THEN UPDT_SEQ
						ELSE #{updtSeq, jdbcType=NUMERIC}
					END
		   )  
WHERE 	1 	= 	1
AND 		ADM_SEQ = #{admSeq, jdbcType=NUMERIC}

INSERT INTO SYS_ADM_AUTH_GRP_MAP (
		ADM_SEQ
	  , AUTH_GRP_SEQ
	  , 	RGST_DT
	  , RGST_SEQ			
)
VALUES (
		#{admSeq, jdbcType=NUMERIC}
	  , 	#{authGrpSeq, jdbcType=NUMERIC}
	  , 	CURRENT_TIMESTAMP(3)
	  , #{rgstSeq, jdbcType=NUMERIC}
)

mapper.delete:
DELETE 
FROM 	SYS_ADM_AUTH_GRP_MAP
WHERE 	1 	= 	1
AND  	ADM_SEQ 			=	#{admSeq, jdbcType=NUMERIC}
AND  	AUTH_GRP_SEQ 	=	#{authGrpSeq, jdbcType=NUMERIC}
